contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to add and then performs addToBalance (sending that amount) and withdrawBalance.
    // It asserts that after withdrawal the stored balance for this contract is zero and that address(c).balance
    // did not increase as a result of the withdraw (i.e., funds were forwarded out), by checking the contract's
    // recorded balance becomes zero and the c contract's balance is at most its previous balance minus the withdrawn amount.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test contract balance");

        // Read c's balance before deposit
        uint cBalBefore = address(c).balance;
        // Read stored user balance for this contract (should start 0 for fresh c)
        uint storedBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // Call addToBalance forwarding `amount` wei to c
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        // After deposit, stored balance must have increased by exactly amount
        uint storedAfterDeposit = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        // Capture c balance after deposit
        uint cBalAfterDeposit = address(c).balance;

        // Now attempt withdraw; capture whether it reverted
        bool didRevert;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // Read stored balance after withdrawal attempt and c's balance after
        uint storedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        // General rule asserted:
        // If withdrawBalance did not revert, then stored balance for this contract must be zero afterwards,
        // and c's balance must be <= cBalAfterDeposit - (storedAfterDeposit) (i.e., c lost at least the withdrawn amount).
        // If withdrawBalance reverted, no requirement about balances changing (but storedAfter must equal storedAfterDeposit if withdraw reverted).
        assert(
            (didRevert && storedAfter == storedAfterDeposit)
            || (!didRevert && storedAfter == 0 && cBalAfter + storedAfterDeposit <= cBalAfterDeposit)
        );
    }

    // Allow receiving Ether when c calls back
    receive() external payable {}
}

