// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint cBalBefore = address(c).balance;
        uint256 storedBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { storedBefore = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 storedAfterDeposit;
        try c.getBalance(address(this)) returns (uint256 __r) { storedAfterDeposit = __r; } catch { return; }
        uint cBalAfterDeposit = address(c).balance;
        bool didRevert;
        try c.withdrawBalance() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 storedAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { storedAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue((didRevert && storedAfter == storedAfterDeposit)
            || (!didRevert && storedAfter == 0 && cBalAfter + storedAfterDeposit <= cBalAfterDeposit));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
